  const calendarPage=()=>{const m=meta(),c=readConfig(),state=stateFor(),rows=state.rows||[],total=totalHours(rows),lecture=rows.reduce((s,r)=>s+Number(r.lectureHours||0),0),experiment=rows.reduce((s,r)=>s+Number(r.experimentHours||0),0),practice=rows.reduce((s,r)=>s+Number(r.practiceHours||0),0),covered=rows.filter(r=>String(r.lecture||'').trim()&&String(r.lecture||'').trim()!=='—').length,syllabusHours=m.syllabusHours||m.hours,mismatch=total!==syllabusHours,isArch=archived();const rowsHtml=rows.map((row,i)=>`<tr data-week="${esc(row.id)}" class="${row.status==='edited'?'row-draft':''}${row.weekStatus==='holiday'||row.weekStatus==='suspended'?' row-exception':''}"><td class="week-col"><b>${esc(row.week||('第 '+(i+1)+' 周'))}</b><small class="week-date">${esc(rangeFor(i,c))}</small><span class="week-status-badge ${row.weekStatus==='holiday'||row.weekStatus==='suspended'?'warn':''}">${esc(statusNames[row.weekStatus]||'教学周')}</span></td><td class="hours-cell">${Number(row.lectureHours||0)}</td><td class="hours-cell">${Number(row.experimentHours||0)}</td><td class="hours-cell">${Number(row.practiceHours||0)}</td><td><div class="cell-content"><span class="calendar-node-badge">${esc(itemNames[row.itemType]||'章节授课')}</span>${br(row.lecture||'—')}</div><small class="cell-note">${esc(methodNames[row.teachingMethod]||row.teachingMethod||'讲授')}</small></td><td><div class="cell-content muted">${br(row.practice||'—')}</div></td><td><div class="cell-content">${br(row.homework||'—')}</div>${row.homeworkDue?`<small class="cell-note">截止 ${esc(row.homeworkDue)}</small>`:''}</td><td>${esc(row.teacher||m.teacher)}</td><td><button class="table-action" ${isArch?'disabled class="table-action calendar-readonly"':''} onclick="openCalendarEdit(${i})">编辑</button></td></tr>`).join('');return `<div class="eyebrow">教学日历 / CALENDAR</div><div class="title-row calendar-title-row"><div><h1>教学日历 <span class="title-subtitle">${m.id==='discrete'?'学校模板结构化编辑':'课程日历结构化编辑'}</span></h1><p class="calendar-subline">${esc(m.name)} · ${esc(m.term)} · ${esc(m.code)}</p></div><div class="calendar-title-actions"><span id="calendarStatus" class="tag ${state.status==='archived'?'gray':''}">${esc(isArch?'已归档':({draft:'草稿',editing:'编辑中',pending_review:'待审核',approved:'已通过',empty:'未建立'}[state.status]||'草稿'))}</span><button class="btn secondary" ${isArch?'disabled class="btn secondary calendar-readonly"':''} onclick="openCalendarAI()">✦ AI 排课建议</button></div></div>${isArch?'<div class="calendar-archive-notice"><b>已归档 · 只读</b><span>课程归档后保留历史日历的查看与导出能力，编辑、AI 建议、复制版本和提交审核均已停用。</span></div>':''}${sourceCard(m,c)}${configCard(c)}${signatureCard(m)}${exceptionSummary(c)}<div class="stats calendar-stats"><div class="stat"><span>计划总学时 / 正式大纲</span><strong>${total} / ${syllabusHours}</strong><em class="${mismatch?'warn-text':''}">${mismatch?'相差 '+Math.abs(total-syllabusHours)+' 学时':'已与正式大纲对齐'}</em></div><div class="stat"><span>讲授 / 实验 / 实践</span><strong>${lecture} / ${experiment} / ${practice}</strong><em>学校模板基准 ${m.lecture} / ${m.experiment} / ${m.practice}</em></div><div class="stat"><span>章节覆盖</span><strong>${covered} / ${rows.length} 周</strong><em>${m.id==='discrete'?'正式内容已排入日历':'尚未建立课程内容'}</em></div><div class="stat"><span>当前版本</span><strong>${esc(state.version||'v3')}</strong><em>最近更新 ${state.updatedAt?'2026-09-04':'尚未建立'}</em></div></div>${mismatch?`<div class="notice warn calendar-warning"><b>学时待核对</b><span>当前结构化日历为 ${total} 学时，正式大纲 ${syllabusHours} 学时；${m.id==='discrete'?'学校模板原文为 '+m.hours+' 学时。':'该课程尚未导入学校模板。'}此差异会阻止提交审核，请先对齐大纲与日历。</span>${m.id==='discrete'?'<a class="overview-link" href="#course/syllabus">去教学大纲 →</a>':''}</div>`:''}<section class="panel calendar-plan-panel"><div class="calendar-plan-head"><div><h2>平台结构化编辑</h2><p>逐周维护授课内容、教学节点、实验 / 实践安排与课外作业；学校原文作为来源保留。</p></div><div class="calendar-plan-actions"><button class="btn secondary" onclick="checkCalendar()">检查日历</button><button class="btn secondary" onclick="openCalendarExport()">导出模板</button><button class="btn primary" ${isArch?'disabled class="btn primary calendar-readonly"':''} onclick="submitCalendarReview()">提交审核</button></div></div><div class="calendar-table-wrap"><table class="calendar-table"><thead><tr><th class="week-col">周次 / 日期</th><th class="hours-col">讲授</th><th class="hours-col">实验</th><th class="hours-col">实践</th><th class="content-col">讲授内容</th><th class="practice-col">实验或实践内容</th><th class="homework-col">课外作业</th><th class="teacher-col">授课教师</th><th class="action-col">操作</th></tr></thead><tbody>${rowsHtml}</tbody></table></div><div class="calendar-table-note"><span>共 ${rows.length} 周 · 每周 ${esc(c.weekly||'待配置')} 学时</span><span>日期、教学节点、教学方式和作业截止时间均可在周计划编辑中维护</span></div></section><div class="calendar-lower-grid"><section class="panel"><div class="head"><h2>学时与规则校验</h2><span class="tag ${mismatch?'':'ok'}">${mismatch?'需要处理':'已通过'}</span></div><div class="rule-list"><div><span>日历总学时 = 正式大纲总学时（${syllabusHours}）</span><b class="${mismatch?'rule-fail':'rule-pass'}">${mismatch?'未通过':'通过'}</b></div><div><span>学校模板原文总学时（${m.hours}）已保留</span><b class="rule-pass">已记录</b></div><div><span>正式授课章节全部覆盖</span><b class="rule-pass">${covered===rows.length?'通过':'待补充'}</b></div><div><span>AI 不修改校历与正式学时</span><b class="rule-pass">通过</b></div></div><p class="rule-footnote">错误会阻止提交；warning 需教师确认后才能提交。当前页面为 Mock 数据模式。</p></section><section class="panel"><div class="head"><h2>版本与审核</h2><a class="overview-link" href="#course/version-review">统一审核中心 →</a></div><div class="version-card"><div><span class="eyebrow">当前日历</span><strong>${esc(isArch?'v2':(state.version||'v3'))} · ${esc(isArch?'已归档':({draft:'草稿',editing:'编辑中',pending_review:'待审核',approved:'已通过'}[state.status]||'草稿'))}</strong><small>${m.id==='discrete'?'学校模板导入 · 2026-09-04 10:24':'尚未导入学校模板'}</small></div><span class="tag ${isArch?'gray':''}">${esc(isArch?'已归档':({draft:'草稿',editing:'编辑中',pending_review:'待审核',approved:'已通过'}[state.status]||'草稿'))}</span></div><div class="actions calendar-actions"><button class="btn secondary" ${isArch?'disabled class="btn secondary calendar-readonly"':''} onclick="duplicateCalendarVersion()">复制为新版本</button><button class="btn secondary" onclick="openCalendarReviewLog()">查看变更记录</button></div></section></div>`};
  const writeConfigFromForm=form=>{const next=Object.assign(defaultConfig(),{school:form.elements.school.value.trim()||'尚未配置学校校历',calendarSource:form.elements.calendarSource.value,academicYear:form.elements.academicYear.value.trim(),termType:form.elements.termType.value,termStartDate:form.elements.termStartDate.value,termEndDate:form.elements.termEndDate.value,firstClassDate:form.elements.firstClassDate.value,weeks:form.elements.weeks.value.trim(),weekly:form.elements.weekly.value.trim(),generationMode:form.elements.generationMode.value,classWeekdays:[...form.querySelectorAll('input[name="classWeekdays"]:checked')].map(x=>x.value),includeReviewWeek:form.elements.includeReviewWeek.checked,includeExamWeek:form.elements.includeExamWeek.checked,includeHomeworkPlan:form.elements.includeHomeworkPlan.checked,holiday:form.elements.holiday.value.trim()||'无',makeup:form.elements.makeup.value.trim()||'无',adjust:form.elements.adjust.value.trim()||'无',teacherInstruction:form.elements.teacherInstruction.value.trim(),exceptions:[...form.querySelectorAll('[data-exception-row]')].map(row=>{const get=name=>row.querySelector('[name="'+name+'"]');return {type:get('exceptionType').value,originalDate:get('originalDate').value,targetDate:get('targetDate').value,hoursDelta:Number(get('hoursDelta').value)||0,reason:get('reason').value.trim(),source:get('source').value,confirmed:get('confirmed').checked}})});return next};
  window.openCalendarConfig=function(){if(archived()){toast('课程已归档：校历配置为只读，可查看和导出');return}const c=readConfig();const body=`<form id="calendarConfigForm" class="calendar-edit-form calendar-config-form"><div class="calendar-config-form-grid"><label>学校校历<input name="school" value="${esc(c.school)}"></label><label>校历来源<select name="calendarSource">${selectOptions({school_calendar:'学校校历',manual:'手动配置'},c.calendarSource)}</select></label><label>学年<input name="academicYear" value="${esc(c.academicYear)}"></label><label>学期<select name="termType">${['春季','夏季','秋季','冬季'].map(x=>`<option ${c.termType===x?'selected':''}>${x}</option>`).join('')}</select></label><label>学期开始日期<input name="termStartDate" type="date" value="${esc(c.termStartDate)}"></label><label>学期结束日期<input name="termEndDate" type="date" value="${esc(c.termEndDate)}"></label><label>首次授课日期<input name="firstClassDate" type="date" value="${esc(c.firstClassDate)}"></label><label>教学周数<input name="weeks" type="number" min="1" max="52" value="${esc(c.weeks)}"></label><label>默认周学时<input name="weekly" type="number" min="1" max="40" value="${esc(c.weekly)}"></label><label>生成方式<select name="generationMode">${selectOptions({automatic:'规则自动分配',semi_automatic:'AI 建议后确认',blank:'空白日历'},c.generationMode)}</select></label><fieldset class="span-2"><legend>授课星期</legend><div class="weekday-grid">${['周一','周二','周三','周四','周五','周六','周日'].map(d=>`<label><input type="checkbox" name="classWeekdays" value="${d}" ${(c.classWeekdays||[]).includes(d)?'checked':''}>${d}</label>`).join('')}</div></fieldset><fieldset class="span-2"><legend>教学节点</legend><div class="calendar-toggle-grid"><label class="calendar-toggle"><input type="checkbox" name="includeReviewWeek" ${c.includeReviewWeek?'checked':''}>包含复习周</label><label class="calendar-toggle"><input type="checkbox" name="includeExamWeek" ${c.includeExamWeek?'checked':''}>包含考试周</label><label class="calendar-toggle"><input type="checkbox" name="includeHomeworkPlan" ${c.includeHomeworkPlan?'checked':''}>包含作业计划</label></div></fieldset><label>节假日 / 停课摘要<input name="holiday" value="${esc(c.holiday)}" placeholder="例：清明节 4/4 停课"></label><label>补课安排摘要<input name="makeup" value="${esc(c.makeup)}" placeholder="例：4/6 补第 5 周周一"></label><label>调课记录摘要<input name="adjust" value="${esc(c.adjust)}" placeholder="例：第 8 周改为线上授课"></label><label>教师特殊安排<input name="teacherInstruction" value="${esc(c.teacherInstruction)}" placeholder="最多 2000 字"></label></div><section class="exception-editor"><div class="exception-editor-head"><div><b>例外日期明细</b><small>对应学校模板之外的节假日、停课、补课和调课记录</small></div><button type="button" class="btn secondary" id="calendarExceptionAdd">＋ 添加例外</button></div><div class="exception-table-wrap"><table class="exception-table"><thead><tr><th>类型</th><th>原日期</th><th>目标日期</th><th>学时变更</th><th>原因</th><th>来源</th><th>确认</th><th></th></tr></thead><tbody id="calendarExceptionRows">${(c.exceptions||[]).map((x,i)=>exceptionRow(x,i)).join('')}</tbody></table></div><p class="calendar-edit-hint">停课学时填负数，补课填正数；未确认的记录会在日历检查中提示 warning。</p></section><p id="calendarConfigError" class="calendar-form-error" hidden></p></form>`;modalOpen('配置校历与周次','教学日历 · 校历设置','学校模板规则 · Mock 数据',body,'保存配置',()=>{const form=document.getElementById('calendarConfigForm'),error=document.getElementById('calendarConfigError');if(!form)return;const start=asDate(form.elements.termStartDate.value),end=asDate(form.elements.termEndDate.value),weeks=Number(form.elements.weeks.value),weekly=Number(form.elements.weekly.value);if(start&&end&&end<=start){error.textContent='学期结束日期必须晚于开始日期。当前操作未保存，请修正后重试。';error.hidden=false;return}if(!weeks||weeks<1||weeks>52||!weekly||weekly<1||weekly>40){error.textContent='教学周数需为 1–52，周学时需为 1–40。当前操作未保存，请修正后重试。';error.hidden=false;return}const next=writeConfigFromForm(form);try{localStorage.setItem(configKey(),JSON.stringify(next))}catch{}window.closeAI();toast('校历配置已保存，例外日期将参与下一次日历检查');setTimeout(()=>window.render(),220)});const add=document.getElementById('calendarExceptionAdd');const rows=document.getElementById('calendarExceptionRows');if(add&&rows){add.onclick=()=>{rows.insertAdjacentHTML('beforeend',exceptionRow({},rows.children.length));bindExceptionRemove()};bindExceptionRemove()}};
  const bindExceptionRemove=()=>document.querySelectorAll('.exception-remove').forEach(btn=>{btn.onclick=()=>btn.closest('tr').remove()});
  window.openCalendarEdit=function(index){if(archived()){toast('课程已归档：周计划为只读，可查看和导出');return}const m=meta(),c=readConfig(),state=stateFor(),row=state.rows&&state.rows[index];if(!row)return;const body=`<form id="calendarEditForm" class="calendar-edit-form"><div class="calendar-edit-meta"><div><span>周次</span><b>${esc(row.week||('第 '+(index+1)+' 周'))}</b></div><div><span>日期范围</span><b>${esc(rangeFor(index,c))}</b></div><div><span>课程编号 / 版本</span><b>${esc(m.code)} · ${esc(state.version||'v3')}</b></div></div><div class="calendar-config-form-grid"><label>周状态<select name="weekStatus">${selectOptions(statusNames,row.weekStatus||'normal')}</select></label><label>教学节点<select name="itemType">${selectOptions(itemNames,row.itemType||'chapter')}</select></label><label>教学方式<input name="teachingMethod" value="${esc(row.teachingMethod||'讲授')}" placeholder="讲授、讨论、练习"></label><label>授课教师<input name="teacher" value="${esc(row.teacher||m.teacher)}"></label></div><label>讲授内容<textarea name="lecture" required>${esc(row.lecture||'')}</textarea></label><label>实验或实践内容<textarea name="practice">${esc(row.practice||'')}</textarea></label><label>课外作业<textarea name="homework">${esc(row.homework||'')}</textarea></label><div class="calendar-edit-hours"><label>讲授学时<input name="lectureHours" type="number" min="0" max="40" value="${Number(row.lectureHours||0)}"></label><label>实验学时<input name="experimentHours" type="number" min="0" max="40" value="${Number(row.experimentHours||0)}"></label><label>实践学时<input name="practiceHours" type="number" min="0" max="40" value="${Number(row.practiceHours||0)}"></label></div><div class="calendar-config-form-grid"><label>作业发布日期<input name="homeworkPublish" type="date" value="${esc(row.homeworkPublish||'')}"></label><label>作业截止日期<input name="homeworkDue" type="date" value="${esc(row.homeworkDue||'')}"></label></div><label>教师备注<textarea name="teacherNote" placeholder="记录复习、答疑或课堂调整说明">${esc(row.teacherNote||'')}</textarea><p id="calendarEditError" class="calendar-form-error" hidden></p><p class="calendar-edit-hint">本周教学项保存后标记为“编辑中”；正式版本不会被覆盖，提交审核前会重新执行学时、覆盖和作业日期检查。</p></form>`;modalOpen('编辑 '+(row.week||('第 '+(index+1)+' 周')),'教学日历 · 周计划编辑',m.id==='discrete'?'结构化字段 · 来源：学校教学日历 Word 模板':'结构化字段 · 当前课程',body,'保存本周计划',()=>{const form=document.getElementById('calendarEditForm'),error=document.getElementById('calendarEditError');if(!form)return;const publish=form.elements.homeworkPublish.value,due=form.elements.homeworkDue.value;if(publish&&due&&due<publish){error.textContent='作业截止日期不能早于发布日期。当前周计划未保存，请修正后重试。';error.hidden=false;return}const next=Object.assign({},row,{weekStatus:form.elements.weekStatus.value,itemType:form.elements.itemType.value,teachingMethod:form.elements.teachingMethod.value.trim()||'讲授',teacher:form.elements.teacher.value.trim()||m.teacher,lecture:form.elements.lecture.value.trim()||'—',practice:form.elements.practice.value.trim()||'—',homework:form.elements.homework.value.trim()||'—',lectureHours:Math.max(0,Number(form.elements.lectureHours.value)||0),experimentHours:Math.max(0,Number(form.elements.experimentHours.value)||0),practiceHours:Math.max(0,Number(form.elements.practiceHours.value)||0),homeworkPublish:publish,homeworkDue:due,teacherNote:form.elements.teacherNote.value.trim(),status:'edited',course_id:m.id,course_version_id:m.id+'-'+(state.version||'v3')});state.rows[index]=next;state.status='editing';state.updatedAt=new Date().toISOString();saveState(state);window.closeAI();toast((row.week||'本周')+'计划已保存，状态变为编辑中');setTimeout(()=>window.render(),220)});};
  const checkData=()=>{const m=meta(),c=readConfig(),state=stateFor(),rows=state.rows||[],total=totalHours(rows),syllabusHours=m.syllabusHours||m.hours,missing=rows.filter(r=>!String(r.lecture||'').trim()||String(r.lecture).trim()==='—').length,overCapacity=rows.filter(r=>Number(c.weekly)>0&&(Number(r.lectureHours||0)+Number(r.experimentHours||0)+Number(r.practiceHours||0))>Number(c.weekly)).length,invalidHomework=rows.filter(r=>r.homeworkPublish&&r.homeworkDue&&r.homeworkDue<r.homeworkPublish).length,unconfirmed=(c.exceptions||[]).filter(x=>!x.confirmed).length,exceptionConflict=rows.filter(r=>(r.weekStatus==='holiday'||r.weekStatus==='suspended')&&String(r.lecture||'').trim()&&String(r.lecture).trim()!=='—').length;return {m,c,state,total,syllabusHours,missing,overCapacity,invalidHomework,unconfirmed,exceptionConflict}};
  window.checkCalendar=function(){const d=checkData(),items=[['日历总学时 = 正式大纲总学时（'+d.syllabusHours+' 学时）',d.total===d.syllabusHours,d.total===d.syllabusHours?'通过':'未通过'],['16 周计划均已建立',d.missing===0,d.missing?'有 '+d.missing+' 周待补充':'通过'],['单周计划不超过可用周学时',d.overCapacity===0,d.overCapacity?'有 '+d.overCapacity+' 周超出 '+d.c.weekly+' 学时':'通过'],['节假日 / 停课周未安排授课',d.exceptionConflict===0,d.exceptionConflict?'有 '+d.exceptionConflict+' 周存在冲突':'通过'],['作业截止日期不早于发布日期',d.invalidHomework===0,d.invalidHomework?'有 '+d.invalidHomework+' 条日期冲突':'通过'],['例外日期均已确认',d.unconfirmed===0,d.unconfirmed?'有 '+d.unconfirmed+' 条待确认':'通过'],['学校模板字段已保留',d.m.id==='discrete',d.m.id==='discrete'?'已记录':'待上传']];const hasError=items.some(x=>!x[1]&&x[0]!=='例外日期均已确认');const body='<div class="calendar-check-list">'+items.map(x=>'<div class="calendar-check-item '+(x[1]?'pass':'fail')+'"><span>'+esc(x[0])+'</span><b>'+esc(x[2])+'</b></div>').join('')+'</div>'+(hasError?'<p class="calendar-edit-hint">发生了什么：日历存在未通过的规则检查。影响：当前版本不能提交审核。下一步：定位对应周计划或校历例外，修正后重新检查；修正后可重试。</p>':'<p class="calendar-edit-hint" style="background:#eefaf7;color:#167c73">检查完成：当前版本满足提交条件。仍建议教师确认学校校历和签字信息后再提交审核。</p>');modalOpen('日历检查结果','教学日历 · 提交前检查','总学时、覆盖、周容量、例外日期和作业时间关系',body,'关闭',()=>window.closeAI());document.getElementById('calendarModalCancel').style.display='none'};
  window.submitCalendarReview=function(){if(archived()){toast('课程已归档：不能提交审核');return}const d=checkData();if(d.total!==d.syllabusHours||d.missing||d.overCapacity||d.invalidHomework||d.exceptionConflict){toast('提交被阻止：请先通过日历检查，错误会影响审核提交');return}const state=d.state;state.status='pending_review';state.updatedAt=new Date().toISOString();saveState(state);toast('教学日历已提交教学秘书审核');setTimeout(()=>window.render(),220)};
  window.duplicateCalendarVersion=function(){if(archived()){toast('课程已归档：不能复制新版本');return}const state=stateFor(),number=Number(String(state.version||'v3').replace(/[^0-9]/g,''))||3;state.version='v'+(number+1);state.status='editing';state.updatedAt=new Date().toISOString();saveState(state);toast('已复制为 '+state.version+' 草稿，正式版本未被覆盖');setTimeout(()=>window.render(),220)};
  window.openCalendarExport=function(){const d=checkData(),m=d.m,state=d.state,c=d.c;const body='<div class="calendar-export-preview"><strong>'+esc(m.name)+' · '+esc(m.term)+'</strong><span>课程编号：'+esc(m.code)+'　任课教师：'+esc(m.teacher)+'　课程版本：'+esc(state.version||'v3')+'</span><span>导出内容：课程信息、16 周日期范围、讲授 / 实验 / 实践学时、教学节点、授课内容、实验或实践、课外作业、作业日期、授课教师</span><span>校历来源：'+esc(c.school)+' · 例外日期 '+((c.exceptions||[]).length||0)+' 条</span><span>审签栏：任课教师 '+esc(m.teacher)+' · 教研室主任待审核 · 填表日期 '+esc(m.date)+'</span></div><p class="calendar-edit-hint" style="margin-top:12px;background:#eefaf7;color:#167c73">Mock 模式：已生成导出预览。正式系统将按学校 Word 模板生成 Word / Excel / PDF 文件。</p>';modalOpen('导出教学日历','教学日历 · 导出预览','学校模板格式 · Mock 模式',body,'下载预览',()=>{window.closeAI();toast('已生成教学日历导出预览（Mock）')});document.getElementById('calendarModalCancel').textContent='返回'};
